-- 세트 609. 여러 번 실행해도 안전하다 (NOT EXISTS 가드). 원본: 02_quest_set.sql, 03_quest_set609.sql, 05·06·08. docs/specs/spec_pilot_gap_sets.md
INSERT INTO quest_set (id, title, description, sandbox_type, category)
SELECT 609, '스토리지 풀에서 볼륨까지 한 번에: 풀 만들기, 볼륨 만들기, VM 에 붙이기, 정리', 'libvirt 는 디스크 이미지를 스토리지 풀 안의 볼륨으로 관리합니다. 풀 목록에서 자동 시작이 꺼진 풀을 찾고, 디렉터리 풀을 정의해 시작하는 명령, 볼륨을 만들고 VM 에 영구로 붙이는 명령, 어느 VM 도 쓰지 않는 볼륨을 찾는 방법, 풀을 지우는 순서를 연습합니다. 샌드박스에는 libvirt 가 없어 명령은 파일에 적고 목록은 샘플 출력으로 읽습니다.', 'linux', '가상화'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest_set WHERE id = 609);
UPDATE quest_set SET display_order = 869, unit_id = (SELECT id FROM unit WHERE id = 72), icon = '🗄️' WHERE id = 609;

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 609, 1, '자동 시작이 꺼진 활성 풀', '`/tmp/pool_list.log` 는 `virsh pool-list --all` 의 출력입니다. 지금은 시작돼 있지만 **서버를 재부팅하면 시작되지 않을 풀**(상태 active, 자동 시작 no)의 이름을 `/tmp/pool_noauto.txt` 에 저장하세요. (이름만)', '상태 칸과 자동 시작 칸을 함께 보세요. 두 조건을 모두 만족하는 줄은 하나입니다.', 'cat /tmp/pool_list.log
awk ''$2=="active" && $3=="no" {print $1}'' /tmp/pool_list.log > /tmp/pool_noauto.txt
cat /tmp/pool_noauto.txt

# images 는 이미 꺼져 있고(inactive) default 는 자동 시작이 켜져 있다. backup 은 재부팅 뒤 꺼진 채로 남아, 그 풀의 볼륨을 쓰는 VM 이 시작에 실패한다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/pool_list.log <<''EOF''\\n Name      State      Autostart\\n-----------------------------------\\n default   active     yes\\n images    inactive   no\\n backup    active     no\\nEOF\\ncat > /tmp/vol_list.log <<''EOF''\\n Name          Path\\n--------------------------------------------\\n web01.qcow2   /data/images/web01.qcow2\\n web02.qcow2   /data/images/web02.qcow2\\n old.qcow2     /data/images/old.qcow2\\nEOF\\ncat > /tmp/blk.log <<''EOF''\\n Target   Source\\n------------------------------------------\\n vda      /data/images/web01.qcow2\\n vdb      /data/images/web02.qcow2\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/pool_noauto.txt)\\" = backup ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "backup 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/pool_noauto.txt)\\" = backup ]"]}]', '[{"title": "libvirt 스토리지 풀", "url": "https://libvirt.org/storage.html"}, {"title": "virsh 명령", "url": "https://libvirt.org/manpages/virsh.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 609 AND order_index = 1);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 609, 2, '디렉터리 풀 정의와 시작', '`/data/images` 디렉터리를 쓰는 디렉터리형 풀 `images` 를 **정의하고, 시작하고, 서버 부팅 때 자동 시작되게** 하는 `virsh` 명령을 `/tmp/pool_cmds.txt` 에 한 줄에 하나씩 적으세요. (샌드박스에는 libvirt 가 없어 실행하지 않습니다. 줄 순서는 정의가 먼저여야 합니다)', '인자 순서는 `virsh help` 로 확인하세요. 시작과 자동 시작은 각각 별도의 하위 명령입니다.', 'printf ''%s\\n'' ''virsh pool-define-as images dir --target /data/images'' ''virsh pool-start images'' ''virsh pool-autostart images'' > /tmp/pool_cmds.txt
cat /tmp/pool_cmds.txt

# 정의만 하면 풀은 inactive 다. 시작(pool-start)과 자동 시작(pool-autostart)은 별개의 설정이다. 디렉터리가 없으면 pool-build 가 먼저 필요하다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/pool_list.log <<''EOF''\\n Name      State      Autostart\\n-----------------------------------\\n default   active     yes\\n images    inactive   no\\n backup    active     no\\nEOF\\ncat > /tmp/vol_list.log <<''EOF''\\n Name          Path\\n--------------------------------------------\\n web01.qcow2   /data/images/web01.qcow2\\n web02.qcow2   /data/images/web02.qcow2\\n old.qcow2     /data/images/old.qcow2\\nEOF\\ncat > /tmp/blk.log <<''EOF''\\n Target   Source\\n------------------------------------------\\n vda      /data/images/web01.qcow2\\n vdb      /data/images/web02.qcow2\\nEOF\\ntrue"]', '["sh", "-c", "( grep -E \\"pool-define-as\\" /tmp/pool_cmds.txt | grep -Eq \\"images\\" && grep -E \\"pool-define-as\\" /tmp/pool_cmds.txt | grep -Eq \\"(^|[[:space:]])dir([[:space:]]|$)\\" && grep -E \\"pool-define-as\\" /tmp/pool_cmds.txt | grep -q \\"/data/images\\" ) && ( grep -Eq \\"virsh( (-c|--connect)[ =]?[^ ]+)? pool-start images[[:space:]]*$\\" /tmp/pool_cmds.txt ) && ( grep -Eq \\"virsh( (-c|--connect)[ =]?[^ ]+)? pool-autostart images[[:space:]]*$\\" /tmp/pool_cmds.txt ) && ( [ \\"$(grep -n pool-define-as /tmp/pool_cmds.txt | head -1 | cut -d: -f1)\\" -lt \\"$(grep -n pool-start /tmp/pool_cmds.txt | head -1 | cut -d: -f1)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "풀을 정의한다", "cmd": ["sh", "-c", "grep -E \\"pool-define-as\\" /tmp/pool_cmds.txt | grep -Eq \\"images\\" && grep -E \\"pool-define-as\\" /tmp/pool_cmds.txt | grep -Eq \\"(^|[[:space:]])dir([[:space:]]|$)\\" && grep -E \\"pool-define-as\\" /tmp/pool_cmds.txt | grep -q \\"/data/images\\""]}, {"label": "풀을 시작한다", "cmd": ["sh", "-c", "grep -Eq \\"virsh( (-c|--connect)[ =]?[^ ]+)? pool-start images[[:space:]]*$\\" /tmp/pool_cmds.txt"]}, {"label": "자동 시작을 켠다", "cmd": ["sh", "-c", "grep -Eq \\"virsh( (-c|--connect)[ =]?[^ ]+)? pool-autostart images[[:space:]]*$\\" /tmp/pool_cmds.txt"]}, {"label": "정의가 시작보다 앞이다", "cmd": ["sh", "-c", "[ \\"$(grep -n pool-define-as /tmp/pool_cmds.txt | head -1 | cut -d: -f1)\\" -lt \\"$(grep -n pool-start /tmp/pool_cmds.txt | head -1 | cut -d: -f1)\\" ]"]}]', '[{"title": "libvirt 스토리지 풀", "url": "https://libvirt.org/storage.html"}, {"title": "virsh 명령", "url": "https://libvirt.org/manpages/virsh.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 609 AND order_index = 2);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 609, 3, '볼륨 만들기', '풀 `images` 안에 크기 20GiB 의 qcow2 형식 볼륨 `web01.qcow2` 를 만드는 `virsh` 명령 한 줄을 `/tmp/vol_create.txt` 에 적으세요.', '볼륨 하위 명령은 `vol-` 로 시작합니다. 인자 순서는 `virsh help` 로 확인하세요.', 'echo ''virsh vol-create-as images web01.qcow2 20G --format qcow2'' > /tmp/vol_create.txt
cat /tmp/vol_create.txt

# 용량만 주면 기본 형식은 raw 다. qcow2 로 쓰려면 --format 을 명시한다. 만든 볼륨은 vol-list images 로 확인한다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/pool_list.log <<''EOF''\\n Name      State      Autostart\\n-----------------------------------\\n default   active     yes\\n images    inactive   no\\n backup    active     no\\nEOF\\ncat > /tmp/vol_list.log <<''EOF''\\n Name          Path\\n--------------------------------------------\\n web01.qcow2   /data/images/web01.qcow2\\n web02.qcow2   /data/images/web02.qcow2\\n old.qcow2     /data/images/old.qcow2\\nEOF\\ncat > /tmp/blk.log <<''EOF''\\n Target   Source\\n------------------------------------------\\n vda      /data/images/web01.qcow2\\n vdb      /data/images/web02.qcow2\\nEOF\\ntrue"]', '["sh", "-c", "( grep -Eq \\"virsh( (-c|--connect)[ =]?[^ ]+)? vol-create-as( |$)\\" /tmp/vol_create.txt ) && ( grep -Eq \\"(^|[[:space:]=])images([[:space:]]|$)\\" /tmp/vol_create.txt && grep -Eq \\"(^|[[:space:]=])web01\\\\.qcow2([[:space:]]|$)\\" /tmp/vol_create.txt ) && ( grep -Eq \\"(^|[[:space:]=])(20G|20GiB|21474836480)([[:space:]]|$)\\" /tmp/vol_create.txt ) && ( grep -Eq -- \\"--format[ =]qcow2\\" /tmp/vol_create.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "vol-create-as 로 만든다", "cmd": ["sh", "-c", "grep -Eq \\"virsh( (-c|--connect)[ =]?[^ ]+)? vol-create-as( |$)\\" /tmp/vol_create.txt"]}, {"label": "풀과 볼륨 이름이다", "cmd": ["sh", "-c", "grep -Eq \\"(^|[[:space:]=])images([[:space:]]|$)\\" /tmp/vol_create.txt && grep -Eq \\"(^|[[:space:]=])web01\\\\.qcow2([[:space:]]|$)\\" /tmp/vol_create.txt"]}, {"label": "용량이 20GiB 다", "cmd": ["sh", "-c", "grep -Eq \\"(^|[[:space:]=])(20G|20GiB|21474836480)([[:space:]]|$)\\" /tmp/vol_create.txt"]}, {"label": "qcow2 형식이다", "cmd": ["sh", "-c", "grep -Eq -- \\"--format[ =]qcow2\\" /tmp/vol_create.txt"]}]', '[{"title": "libvirt 스토리지 풀", "url": "https://libvirt.org/storage.html"}, {"title": "virsh 명령", "url": "https://libvirt.org/manpages/virsh.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 609 AND order_index = 3);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 609, 4, 'VM 에 볼륨을 영구로 붙이기', '만든 볼륨 `/data/images/web01.qcow2` 를 실행 중인 VM `db01` 에 디스크 `vdb` 로 붙이되, **VM 을 껐다 켜도 유지되고 형식이 qcow2 로 인식되게** 하는 `virsh` 명령 한 줄을 `/tmp/attach.txt` 에 적으세요.', '인자 순서는 `virsh help` 로 확인하세요. 영구 반영과 이미지 형식을 지정하는 옵션이 필요합니다.', 'echo ''virsh attach-disk db01 /data/images/web01.qcow2 vdb --persistent --subdriver qcow2'' > /tmp/attach.txt
cat /tmp/attach.txt

# --subdriver qcow2 를 빼면 qcow2 파일이 raw 로 붙어 게스트가 읽지 못한다. --persistent 가 없으면 실행 중인 VM 에만 붙고 재부팅하면 사라진다. 여러 VM 이 한 이미지를 동시에 쓰면 데이터가 깨지므로 붙이기 전에 다른 VM 이 쓰는지 확인한다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/pool_list.log <<''EOF''\\n Name      State      Autostart\\n-----------------------------------\\n default   active     yes\\n images    inactive   no\\n backup    active     no\\nEOF\\ncat > /tmp/vol_list.log <<''EOF''\\n Name          Path\\n--------------------------------------------\\n web01.qcow2   /data/images/web01.qcow2\\n web02.qcow2   /data/images/web02.qcow2\\n old.qcow2     /data/images/old.qcow2\\nEOF\\ncat > /tmp/blk.log <<''EOF''\\n Target   Source\\n------------------------------------------\\n vda      /data/images/web01.qcow2\\n vdb      /data/images/web02.qcow2\\nEOF\\ntrue"]', '["sh", "-c", "( grep -Eq \\"virsh( (-c|--connect)[ =]?[^ ]+)? attach-disk db01 /data/images/web01\\\\.qcow2 vdb( |$)\\" /tmp/attach.txt ) && ( grep -Eq -- \\"--(persistent|config)\\" /tmp/attach.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "attach-disk 로 붙인다", "cmd": ["sh", "-c", "grep -Eq \\"virsh( (-c|--connect)[ =]?[^ ]+)? attach-disk db01 /data/images/web01\\\\.qcow2 vdb( |$)\\" /tmp/attach.txt"]}, {"label": "영구 옵션이 있다", "cmd": ["sh", "-c", "grep -Eq -- \\"--(persistent|config)\\" /tmp/attach.txt"]}]', '[{"title": "libvirt 스토리지 풀", "url": "https://libvirt.org/storage.html"}, {"title": "virsh 명령", "url": "https://libvirt.org/manpages/virsh.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 609 AND order_index = 4);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 609, 5, '쓰이지 않는 볼륨 찾기', '`/tmp/vol_list.log` 는 풀의 `vol-list`, `/tmp/blk.log` 는 모든 VM 의 `domblklist` 를 이어 붙인 출력입니다. **어느 VM 에도 붙어 있지 않은 볼륨의 이름**을 `/tmp/unused.txt` 에 저장하세요. (이름만)', '볼륨 목록의 경로가 디스크 목록에 있는지 하나씩 대조하세요.', 'for p in $(awk ''NR>2 {print $2}'' /tmp/vol_list.log); do grep -q "$p" /tmp/blk.log || basename "$p"; done > /tmp/unused.txt
cat /tmp/unused.txt

# 실제 정리 전에는 VM 정의 XML 과 스냅샷 백킹 체인도 확인한다. 목록에 없어도 다른 호스트의 VM 이 쓸 수 있다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/pool_list.log <<''EOF''\\n Name      State      Autostart\\n-----------------------------------\\n default   active     yes\\n images    inactive   no\\n backup    active     no\\nEOF\\ncat > /tmp/vol_list.log <<''EOF''\\n Name          Path\\n--------------------------------------------\\n web01.qcow2   /data/images/web01.qcow2\\n web02.qcow2   /data/images/web02.qcow2\\n old.qcow2     /data/images/old.qcow2\\nEOF\\ncat > /tmp/blk.log <<''EOF''\\n Target   Source\\n------------------------------------------\\n vda      /data/images/web01.qcow2\\n vdb      /data/images/web02.qcow2\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/unused.txt)\\" = old.qcow2 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "old.qcow2 다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/unused.txt)\\" = old.qcow2 ]"]}]', '[{"title": "libvirt 스토리지 풀", "url": "https://libvirt.org/storage.html"}, {"title": "virsh 명령", "url": "https://libvirt.org/manpages/virsh.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 609 AND order_index = 5);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 609, 6, '풀을 멈추면', '`virsh pool-destroy images` 를 실행했습니다. 결과로 알맞은 것은?', '이름은 파괴처럼 보이지만 풀의 상태를 바꾸는 명령입니다.', NULL, NULL, '[]', 'choice', '["풀과 풀 안의 모든 볼륨 파일이 디스크에서 삭제된다", "풀 정의가 사라져 다시 시작할 수 없게 된다", "풀 안의 볼륨을 쓰는 VM 이 자동으로 다른 풀로 옮겨진다", "풀이 inactive 가 되고 풀 안의 파일은 디스크에 그대로 남는다"]', 3, 'pool-destroy 는 풀을 중지(inactive)할 뿐 파일을 지우지 않습니다. 정의까지 없애려면 pool-undefine 이 필요하고, 파일 삭제는 vol-delete 가 하고 pool-delete 는 대상 디렉터리 자체를 지웁니다. 중지된 풀의 볼륨을 쓰는 VM 은 시작하지 못합니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 609 AND order_index = 6);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 609, 7, '목록이 안 맞을 때', '`virsh` 밖에서 `/data/images` 에 이미지 파일을 직접 복사해 넣었는데 `virsh vol-list images` 에 나타나지 않습니다. 가장 알맞은 조치는?', '풀은 디렉터리 내용을 기억해 두었다가 갱신 요청을 받으면 다시 읽습니다.', NULL, NULL, '[]', 'choice', '["`pool-destroy` 후 `pool-undefine` 으로 풀을 지우고 새로 만든다", "libvirt 를 설치한 서버 전체를 재부팅한다", "`pool-refresh images` 로 풀의 볼륨 목록을 다시 읽게 한다", "`vol-create-as` 로 같은 이름의 볼륨을 새로 만든다"]', 2, '풀은 볼륨 목록을 캐시하므로 외부에서 파일이 바뀌면 pool-refresh 로 갱신합니다. 풀을 지우거나 재부팅할 필요는 없고, 같은 이름으로 만들면 기존 파일과 충돌합니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 609 AND order_index = 7);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 609, 8, '풀 종류 고르기', '여러 호스트가 같은 디스크 이미지를 공유해야 하고 VM 을 호스트 사이에서 라이브 마이그레이션하려 합니다. 풀 구성으로 가장 알맞은 것은?', '이미지가 한 서버의 로컬 디스크에만 있으면 다른 서버는 읽을 수 없습니다.', NULL, NULL, '[]', 'choice', '["각 호스트의 로컬 디렉터리 풀에 같은 이름의 이미지를 따로 둔다", "모든 호스트가 같은 경로로 접근하는 NFS 같은 공유 스토리지의 풀", "이미지를 VM 마다 호스트의 /tmp 에 복사해 둔다", "풀 없이 VM 을 시작할 때마다 파일 경로를 손으로 지정한다"]', 1, '공유 스토리지에서는 출발·도착 호스트가 같은 이미지를 보므로 디스크를 복사하지 않고 메모리만 옮깁니다. 로컬 풀만 있으면 디스크 복사가 필요해 오래 걸리고 이미지가 어긋날 수 있습니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 609 AND order_index = 8);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 609, 9, '풀 새로 읽기', '풀 안 파일이 외부에서 바뀐 뒤 볼륨 목록을 갱신하는 하위 명령의 이름을 채우세요.', '다시 읽는다는 뜻의 영어 단어입니다.', NULL, NULL, '[]', 'fill', '["refresh", "autostart", "build", "undefine"]', NULL, '`pool-refresh` 는 풀의 내용을 다시 스캔해 볼륨 목록을 갱신합니다. `autostart` 는 부팅 때 시작 여부, `build` 는 풀 대상(디렉터리 등)을 준비, `undefine` 은 정의 삭제입니다.', '[0]', 'virsh pool-{0} images', NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 609 AND order_index = 9);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
